        "description": "<div style=\"line-height: 1.7;\"><p style=\"margin-bottom: 12px;\">Задайте для ключа удобное имя.</p><p style=\"padding: 8px 12px; background: #f0fdf4; border-left: 3px solid #10b981; border-radius: 4px; font-size: 13px;\"><b>💡 Варианты именования:</b> «Тестовый ключ», «Производственный», «Мобильный» и т. д.</p></div>",
